// src/areas.js — Kaduna areas config + plot generator + house claiming.
//
// Each area has a name, description, price tier (cheap/middle/rich), and a
// grid of plots. When a player signs up, they pick an area and get assigned
// a free plot via a Firebase transaction on houses/{areaId}/{plotNo}.
//
// Only OCCUPIED plots are stored in Firebase. Empty plots are generated by code.
// The world (src/world.js / src/city.js) renders a simple house model at each
// occupied plot's position with the owner's name on a sign.
//
// Data shape:
//   houses/{areaId}/{plotNo} = { ownerUid, ownerName, tier, colors, locked, forSale, forRent, price, createdAt }
//   players/{uid}/homeArea = "barnawa"
//   players/{uid}/homePlot = 14

import { db } from "./firebase.js";
import { ref, get, set, update, onValue, runTransaction } from "firebase/database";

