// ---- Plot position generator ----
// Plots are arranged in a grid within each area. Returns { x, z, rot } for a plot number.
export function getPlotPosition(area, plotNo) {
  const plotsPerRow = 10;
  const row = Math.floor(plotNo / plotsPerRow);
  const col = plotNo % plotsPerRow;
  const spacing = 8;  // metres between plots
  const startX = area.x - (plotsPerRow * spacing) / 2;
  const startZ = area.z - (area.plots / plotsPerRow * spacing) / 2;
  return {
    x: startX + col * spacing,
    z: startZ + row * spacing,
    rot: (col % 2 === 0) ? 0 : Math.PI,  // alternate facing
  };
}

// Get the area definition by id
export function getArea(areaId) {
  return AREAS.find(a => a.id === areaId);
}

// ---- Claim a plot (Firebase transaction) ----
// Returns { ok, area, plotNo } or { ok: false, reason }
export async function claimPlot(areaId, uid, name, origin) {
  const area = getArea(areaId);
  if (!area) return { ok: false, reason: "Unknown area" };
  // Find a free plot — try plot numbers 0..area.plots-1
  for (let plotNo = 0; plotNo < area.plots; plotNo++) {
    const plotRef = ref(db, "houses/" + areaId + "/" + plotNo);
    let claimed = false;
    try {
      await runTransaction(plotRef, (cur) => {
        if (cur && cur.ownerUid) return; // already taken — abort
        claimed = true;
        // Starting tier depends on origin + area:
        //   attajiri + rich area   → tier 4 (Duplex)
        //   attajiri + middle area → tier 3 (3-Bedroom Bungalow)
        //   attajiri + cheap area  → tier 2 (1-Bedroom Flat)
        //   talaka + rich area     → tier 2 (1-Bedroom Flat) — rare, but possible if they save
        //   talaka + middle area   → tier 1 (Room)
        //   talaka + cheap area    → tier 1 (Room)
        let tier;
        if (origin === "attajiri") {
          tier = area.tier === "rich" ? 4 : area.tier === "middle" ? 3 : 2;
        } else {
          tier = area.tier === "rich" ? 2 : 1;
        }
        return {
          ownerUid: uid,
          ownerName: name,
          tier,
          colors: { wall: area.wallCol, roof: area.roofCol, door: 0x4a3a2a },
          locked: false,
          forSale: false,
          forRent: false,
          price: 0,
          createdAt: Date.now(),
        };
      });
    } catch (e) {
      console.warn("[houses] claim transaction failed:", e);
      continue;
    }
    if (claimed) {
      // Save the player's home area + plot
      // Determine the tier (same logic as above)
      let tier;
      if (origin === "attajiri") {
        tier = area.tier === "rich" ? 4 : area.tier === "middle" ? 3 : 2;
      } else {
        tier = area.tier === "rich" ? 2 : 1;
      }
      await update(ref(db, "players/" + uid), { homeArea: areaId, homePlot: plotNo, homeTier: tier });
      return { ok: true, area, plotNo, tier };
    }
  }
  return { ok: false, reason: "Area is full — try another area" };
}

// ---- Get a player's house info ----
export async function getMyHouse(uid) {
  try {
    const snap = await get(ref(db, "players/" + uid));
    const player = snap.val() || {};
    if (!player.homeArea || player.homePlot == null) return null;
    const houseSnap = await get(ref(db, "houses/" + player.homeArea + "/" + player.homePlot));
    return { area: getArea(player.homeArea), plotNo: player.homePlot, house: houseSnap.val() };
  } catch (e) {
    console.warn("[houses] getMyHouse failed:", e);
    return null;
  }
}

// ---- Listen to occupied houses in an area (for rendering in the world) ----
export function listenToAreaHouses(areaId, callback) {
  return onValue(ref(db, "houses/" + areaId), (snap) => {
    callback(snap.val() || {});
  });
}

// ---- Get all occupied houses for world rendering (per-area, not global) ----
export async function getAreaHouses(areaId) {
  try {
    const snap = await get(ref(db, "houses/" + areaId));
    return snap.val() || {};
  } catch (e) {
    return {};
  }
}

// ---- Check if origin can pick an area ----
export function canPickArea(origin, area) {
  if (origin === "attajiri") return true;  // rich origin can pick any area
  // Talaka can only pick cheap and middle areas
  return area.tier !== "rich";
}
